// Nodo: 1. Pre-procesamiento completo y Mapeo de Palabras Clave

const item = $input.item.json;

// --- FILTRADO INICIAL ---
if (item.event !== 'message') return null;
const payload = item.payload || {};
if ((!payload.body || payload.body.trim() === '') && !payload.hasMedia) return null;
if (payload.type && payload.type !== 'chat') return null;
const remitente = (payload.from || '').toString().trim();
if (!remitente.endsWith('@c.us') && !remitente.endsWith('@lid')) return null;

// --- EXTRACCIÓN DE CAMPOS ---
const clienteTelefonoLimpio = remitente.replace(/@c\.us|@lid/g, '').replace(/\D/g, '');
const chatIdWAHA = remitente;
const mensajeClienteActual = (payload.body || '').trim();

// Saludo según hora
const hora = new Date().getHours();
let saludo;
if (hora < 12) saludo = 'Buenos días';
else if (hora < 19) saludo = 'Buenas tardes';
else saludo = 'Buenas noches';

// --- LÓGICA DE MAPEO DE PALABRAS CLAVE ---
let texto = mensajeClienteActual.toLowerCase().trim();

// Diccionario de sinónimos y términos comunes
const mapeoPalabrasClave = {
    'aguacate': '🥑',
    'aguacates': '🥑',
    'fresa': '🍓',
    'fresas': '🍓',
    'limon': '🍋',
    'limones': '🍋',
    'arandano': '🫐',
    'arandanos': '🫐',
    'mazorca': '🌽',
    'flor de jamaica': '🌺',
    'cebolla': '🧅',
    'zanahoria': '🥕',
    'habichuela': '🫛',
    'mango': '🥭',
    'coco': '🥥',
    'naranja': '🍊',
    'manzana': '🍎',
    'uva': '🍇',
    'pera': '🍐',
    'tomate': '🍅',
    'banano': '🍌',
    'caja': 'caja',
    'malla': 'malla',
    'paquete': 'paquete',
    'combo': 'combo'
};

// Aplicar el mapeo
for (const palabra in mapeoPalabrasClave) {
    if (texto.includes(palabra)) {
        // Reemplazamos la palabra por su valor mapeado para mejorar la búsqueda
        // Damos prioridad a los emojis para productos clave
        texto = texto.replace(new RegExp(palabra, 'g'), mapeoPalabrasClave[palabra]);
    }
}

// Devolver objeto con todos los datos útiles
return [{
  json: {
    clienteTelefonoLimpio,
    chatIdWAHA,
    mensajeClienteActual,
    saludo,
    textoBusqueda: texto,
    datosOriginalesWAHA: item,
    nombre: null
  }
}];

