const inputItem = $input.item.json;
// Para pedidos OlaClick, el mensaje puede estar en diferentes lugares
let mensaje = inputItem.payload?.body || inputItem.mensajeClienteActual || inputItem.datosOriginalesWAHA?.payload?.body;

// Si no encontramos el mensaje en ningún lugar, devolvemos el item original
if (!mensaje) {
  return $input.all();
}

const regexProductos = /X\d+\s+(.*?)\s+\$\s*([\d.,]+)/g;
let match;
const itemsDeSalida = [];

if (!mensaje.includes('Productos')) {
  return $input.all();
}

while ((match = regexProductos.exec(mensaje)) !== null) {
  const nuevoItem = JSON.parse(JSON.stringify(inputItem));
  let nombreProductoOriginal = match[1].trim();
  nombreProductoOriginal = nombreProductoOriginal.replace('🔼', '');
  nombreProductoOriginal = nombreProductoOriginal.replace(/-\\s*\\./, '').trim();
  let nombreParaBuscar = nombreProductoOriginal.toLowerCase().trim();
  nombreParaBuscar = nombreParaBuscar.replace(/^[^\\p{L}\\p{N}]+/u, '').trim();

  nuevoItem.producto_extraido = {
    nombre_en_mensaje: nombreProductoOriginal,
    precio_cliente: match[2].replace(/[.,]/g, ''),
    nombre_para_buscar: nombreParaBuscar
  };
  itemsDeSalida.push({ json: nuevoItem });
}

return itemsDeSalida;

const items = $input.all();
const firstItem = items[0].json;
// Usamos el cuerpo del mensaje original que tiene toda la información
const mensajeCompleto = firstItem.datosOriginalesWAHA.payload.body;

// --- PASO 1: Extraer los valores monetarios directamente del texto ---
// Usamos expresiones regulares para encontrar los números después de cada etiqueta
const subtotalMatch = mensajeCompleto.match(/Subtotal: \$\s*([\d.,]+)/);
const descuentoMatch = mensajeCompleto.match(/Descuento.*?-\$\s*([\d.,]+)/);
const entregaMatch = mensajeCompleto.match(/Entrega: \$\s*([\d.,]+)/);
const totalMatch = mensajeCompleto.match(/\*Total: \$\s*([\d.,]+)/);

// --- PASO 2: Limpiar y convertir los valores a números ---
// Esta función quita los puntos y comas para tener un número puro
const limpiarNumero = (texto) => texto ? parseFloat(texto.replace(/[.,]/g, '')) : 0;

const subtotalFinal = limpiarNumero(subtotalMatch ? subtotalMatch[1] : null);
const descuentoFinal = limpiarNumero(descuentoMatch ? descuentoMatch[1] : null);
const costoEnvioFinal = limpiarNumero(entregaMatch ? entregaMatch[1] : null);
const totalFinal = limpiarNumero(totalMatch ? totalMatch[1] : null);

// --- PASO 3: Construir el carrito de productos (esto no cambia) ---
const carrito = [];
for (const item of items) {
  const prod = item.json.producto_extraido || {};
  const precioNum = Number(prod.precio_cliente);
  if (!isNaN(precioNum)) {
    carrito.push({
      nombre: prod.nombre_en_mensaje,
      precio: precioNum,
      cantidad: 1,
    });
  }
}

// --- PASO 4: Devolver los datos correctos y extraídos ---
return [{
  json: {
    // Usamos los valores reales y finales del mensaje de OlaClick
    subtotal: subtotalFinal,
    descuento: descuentoFinal, // Guardamos el descuento por si lo necesitas
    costo_envio: costoEnvioFinal,
    total: totalFinal,

    validacion_exitosa: true,
    carrito_validado: carrito,

    // Pasamos los datos del cliente para los siguientes nodos
    datosOriginalesWAHA: firstItem.datosOriginalesWAHA,
    clienteTelefonoLimpio: firstItem.clienteTelefonoLimpio,
    chatIdWAHA: firstItem.chatIdWAHA
  }
}];

// --- LÓGICA DE FECHA DE ENTREGA INTELIGENTE ---

function getProximaFechaEntrega() {
    const hoy = new Date();
    const diaActual = hoy.getDay();     // Domingo=0, Lunes=1, Martes=2, etc.
    const horaActual = hoy.getHours();  // Formato 24h (0-23)

    // Definimos tus reglas de negocio como constantes
    const MARTES = 2;
    const VIERNES = 5;
    const HORA_CORTE = 10; // 10:00 AM

    let proximaFecha = new Date(hoy);
    let diasParaSumar = 0;

    // --- Aplicamos tu lógica de negocio ---

    // CASO 1: Si es martes ANTES de las 10 AM, la entrega es HOY.
    if (diaActual === MARTES && horaActual < HORA_CORTE) {
        diasParaSumar = 0; // Se entrega el mismo día
    }
    // CASO 2: Si es martes DESPUÉS de las 10 AM, o es miércoles o jueves.
    else if (diaActual === MARTES || diaActual === 3 || diaActual === 4) {
        // Calculamos los días que faltan para el viernes
        diasParaSumar = (VIERNES - diaActual + 7) % 7;
    }
    // CASO 3: Si es viernes, sábado, domingo o lunes.
    else {
        // Calculamos los días que faltan para el próximo martes
        diasParaSumar = (MARTES - diaActual + 7) % 7;
    }

    // Si el resultado es 0 y ya pasó la hora de corte, debemos saltar a la siguiente entrega
    if (diasParaSumar === 0 && (diaActual === MARTES && horaActual >= HORA_CORTE)) {
         diasParaSumar = (VIERNES - diaActual + 7) % 7; // Salta al viernes
    }


    proximaFecha.setDate(hoy.getDate() + diasParaSumar);

    // Formateamos la fecha para que sea legible
    const opcionesFecha = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
    return proximaFecha.toLocaleDateString('es-ES', opcionesFecha);
}

// Asignamos el resultado al flujo de n8n
$input.item.json.fechaEntregaEstimada = `La próxima fecha de entrega estimada es el ${getProximaFechaEntrega()}`;
return $input.item;

