// Obtener el objeto JSON del item de entrada.
const item = $input.item.json;

// --- LÓGICA DEL NOMBRE ---
// Para evitar errores, comprobamos si 'item.nombre' existe. Si no, usamos un texto vacío.
// Luego, se divide por espacios y se toma solo el primer elemento ().
const primerNombre = (item.nombre |

| '').split(' ');

// --- LÓGICA DEL CARRITO ---
// Se busca 'carrito_validado'. Si no existe o es nulo, se usa una lista vacía.
// Esta es la forma segura y correcta de inicializar la variable.
const carrito = item.carrito_validado ||;

// --- PROCESAMIENTO DEL RESUMEN ---
let resumenProductos = '';
let itemsRestantes = 0;

// Este bloque solo se ejecuta si el carrito tiene uno o más productos.
if (carrito.length > 0) {
  // Se toma un máximo de 4 productos para mostrar en el resumen.
  const itemsAMostrar = carrito.slice(0, 4);

  // Se crea el texto del resumen, uniendo cada nombre de producto con un salto de línea.
  resumenProductos = itemsAMostrar.map(p => `*${p.nombre}*`).join('\n');

  // Se calcula cuántos productos no se mostraron.
  itemsRestantes = carrito.length - itemsAMostrar.length;
}

// Si quedaron productos sin mostrar, se añade una nota al final.
if (itemsRestantes > 0) {
  resumenProductos += `\ny ${itemsRestantes} producto(s) más...`;
}

// --- SALIDA DEL NODO ---
// El nodo de código debe devolver un objeto JSON con los resultados.
return {
  nombreCliente: primerNombre,
  resumenDelPedido: resumenProductos,
  totalItems: carrito.length
};

