const item = $input.item.json;
const estado = item.estado_conversacion;
let ruta;

switch (estado) {
  case 'NUEVO':
  case 'ATENCION_LUZ':
  case 'NOMBRE_SOLICITADO':
  case 'EN_PEDIDO':
  case 'PEDIDO_LISTO':
  case 'PEDIDO_FINALIZADO':
  case 'ESCALADO':
  case 'Pedido OlaClick':
    ruta = estado;
    break;
  default:
    ruta = 'FALLBACK'; // Ruta por defecto para estados no manejados
}

return [{ json: { ...item, ruta } }];
